argv:
S=$PWD/skills/confidence-protocol/scripts/confidence.py; T=$(python3 -c 'import tempfile;print(tempfile.mkdtemp())'); cd $T || exit 1; git init -q r && cd r && echo tracked > f.txt && git add f.txt && git -c user.email=a@b -c user.name=a commit -q -m f 2>/dev/null; R=$T/res.txt; {
echo '--- json failure binary'; python3 -B $S run --json --id b --directory .confidence -- python3 -c 'import sys;sys.stdout.buffer.write(bytes(range(256)));sys.exit(7)' > $T/out.bin 2>$T/err; echo rc=$?; python3 -c 'import sys;print(repr(open(sys.argv[1],"rb").read()), open(sys.argv[2]).read())' $T/out.bin $T/err; python3 -c 'import json,hashlib;r=json.load(open(".confidence/runs/b.json"));d=open(".confidence/runs/b.log","rb").read();print(r["exit_code"],r["workspace_binding"],d==bytes(range(256)),hashlib.sha256(d).hexdigest()==r["log_sha256"])';
echo '--- json tracked mutation'; python3 -B $S run --json --id m --directory .confidence -- python3 -c 'open("f.txt","a").write("x")' 2>/dev/null; echo rc=$?;
echo '--- json untracked creation'; python3 -B $S run --json --id u --directory .confidence -- python3 -c 'open("new.py","w").write("x")' 2>/dev/null; echo rc=$?;
echo '--- json no-op'; python3 -B $S run --json --id n --directory .confidence -- python3 -c 'print(1)' 2>/dev/null; echo rc=$?;
echo '--- default replay'; python3 -B $S run --id d --directory .confidence -- python3 -c 'print("hello")' 2>/dev/null; echo rc=$?;
echo '--- non-git'; mkdir -p $T/ng; python3 -B $S run --json --id g --directory $T/ng/.c --cwd $T/ng -- python3 -c 'pass' 2>/dev/null; echo rc=$?;
echo '--- validate record'; python3 -B -c 'import sys;sys.path.insert(0,sys.argv[1]);import confidence as c;from pathlib import Path;print(c.validate_run_record(Path(".confidence"),"b")[1])' $(dirname $S);
} > $R 2>&1; while IFS= read -r l; do echo "$l"; done < $R
